message.content:
{
  "description": "The creature is shown in strict left-facing profile standing on two hind legs against a plain off-white background. It has the head, ears, hind legs and long bushy tail of a reddish fox combined with the torso, chest and folded wings of a barn owl. The head is narrow and pointed with reddish-orange fur, the body is upright and covered in dense feathers that are white with black spots on the chest and mottled buff, tan and grey on the back and wings, and the rear and lower limbs are covered in reddish-brown fur that transitions to scaly, clawed feet. The overall posture is that of a bipedal animal standing on the ground with its tail extending behind and its wings folded close to its sides.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a fox head in left profile with a long pointed muzzle, black nose, white fur on the muzzle, chin and lower cheek, reddish-orange fur on the face and forehead, a visible brown eye with fine whiskers around the muzzle, facing left at the front of the body"
    ,
      "where": "at the anterior end of the body on top of the feathered neck"
    },
    {
      "part": "ears",
      "looks_like": "two upright triangular pointed ears with reddish-orange outer fur, black on the tips and rear edges, and pale cream to white inner fur with dark interior shading",
      "where": "on top of the head, one slightly behind the other in profile"
    },
    {
      "part": "legs",
      "looks_like": "two thick muscular hind legs with dense reddish-brown and greyish-white fur on the thighs, the lower shanks becoming bare with a rough, scaly, brownish texture and visible joints bent in a digitigrade stance",
      "where": "under the posterior half of the body, supporting the weight on the ground"
    },
    {
      "part": "feet",
      "looks_like": "two large feet with thick toes ending in strong dark brown to black curved claws/talons, the skin appearing scaly and rough with small pebbles displaced beneath",
      "where": "at the distal ends of the two hind legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "one long, thick, very bushy tail covered in long reddish-brown fur that is darker along the top and paler below, ending in a white tip, with individual hairs visible",
      "where": "extending from the rear of the body behind the wings and legs, angled down and back to the right"
    },
    {
      "part": "wings",
      "looks_like": "two folded wings with layered flight feathers in mottled patterns of buff, tan, orange-brown, grey and white, the primaries showing distinct dark brown barring and the coverts showing grey with white speckles",
      "where": "folded along the left and right sides of the feathered torso, overlapping the upper hind legs"
    },
    {
      "part": "feathers",
      "looks_like": "dense soft feathering covering the neck, chest, back and wings; the throat and chest are white to pale buff with small black spots, the back and wing coverts are mottled grey, buff and orange-brown with intricate speckling",
      "where": "covering the entire torso from the base of the fox head to the base of the tail, including the wings"
    },
    {
      "part": "scales",
      "looks_like": "small rough scale-like texture and wrinkled skin on the lower legs and feet, brown in color",
      "where": "on the lower portion of both hind legs and on the feet"
    },
    {
      "part": "markings",
      "looks_like": "numerous small black dots scattered over the white chest and throat, and dark brown to black transverse bars and speckles on the tan and grey wing and back feathers",
      "where": "on the chest, throat, back and wings"
    }
  ],
  "attached_objects": [],
  "animals": [
    "fox",
    "barn owl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
